<?php
namespace App\Controllers\Api\V1;
use App\Core\ApiController; use App\Services\Communication\CommunicationProviderService; use App\Validation\CommunicationProviderValidation; use Throwable;
class CommunicationProviderController extends ApiController { public function __construct(private readonly CommunicationProviderService $service=new CommunicationProviderService()){} public function index(){try{return $this->ok('Communication provider listesi getirildi',$this->service->list($this->request->getGet()));}catch(Throwable $e){return $this->failFromException($e);}} public function create(){try{$p=$this->apiValidator->validateOrFail($this->request->getJSON(true)??[],CommunicationProviderValidation::createRules()); return $this->ok('Communication provider olusturuldu',$this->service->create($p));}catch(Throwable $e){return $this->failFromException($e);}} public function show($id=null){try{return $this->ok('Communication provider getirildi',$this->service->show((int)$id));}catch(Throwable $e){return $this->failFromException($e);}} public function update($id=null){try{$p=$this->apiValidator->validateOrFail($this->request->getJSON(true)??[],CommunicationProviderValidation::updateRules()); return $this->ok('Communication provider guncellendi',$this->service->update((int)$id,$p));}catch(Throwable $e){return $this->failFromException($e);}} public function delete($id=null){try{$this->service->delete((int)$id); return $this->ok('Communication provider silindi');}catch(Throwable $e){return $this->failFromException($e);}} public function setDefault($id=null){try{return $this->ok('Communication provider default ayarlandi',$this->service->setDefault((int)$id));}catch(Throwable $e){return $this->failFromException($e);}} }
